function walk(l,a){if(l.name.indexOf('link:')===0)a.push(l.name);(l.layers||[]).forEach(k=>walk(k,a));}doc.pages.filter(p=>/^Proto macOS /.test(p.name)).forEach(p=>p.layers.filter(l=>l.name.indexOf('Screen/macos/')===0&&l.name.split('/')[4].indexOf('settings')===0).forEach(s=>{var links=[];walk(s,links);H.out({page:p.name,id:s.name.split('/')[4],frame:String(s.id),x:s.frame.x,y:s.frame.y,w:s.frame.width,h:s.frame.height,links:Array.from(new Set(links)).sort()});}));